parameters.jsCode:
// TEST-ONLY Code node: "Test Failure Injection"  (exists only in the TEST-webhook build, never in the submitted workflow)
// Sits between the agent and "Output Checks". When the webhook body contains `test_mode`, it corrupts the agent's
// answer for the first `fail_attempts` attempts so the guardrail (checks -> retry with reasons -> manual routing)
// can be demonstrated live on demand. Without `test_mode` it passes the answer through untouched.
//
//   test_mode      what it corrupts                                           which check should react
//   bad_team       primary_team -> "Payments" (not an exact directory name)   check 1
//   fake_incident  matched_incident_id -> "INC-999" (not in the history)      check 3
//   passive_action first_action -> "Just monitor the situation."              check 2 (only when severity is high)
//   bad_tone       tone -> "calm_informational" (every attempt)               decision validation (a warning, not a retry)
//   fail_attempts  how many attempts to corrupt: 1 (default), 2, or 99 = always
//
// $runIndex = 0 on the first attempt, 1 on retry 1, 2 on retry 2.

const raw = $input.first().json;

let body = {};
try {
  body = $('Test Webhook').first().json.body ?? {};
} catch (e) {
  body = {};
}

const mode = String(body.test_mode ?? '').trim();
const failAttempts = Number.isFinite(Number(body.fail_attempts)) ? Number(body.fail_attempts) : 1;
const attempt = $runIndex;

if (!mode || !raw.output || typeof raw.output !== 'object') {
  return [{ json: raw }];
}

const out = { ...raw.output };
const corrupt = attempt < failAttempts;

if (mode === 'bad_team' && corrupt) out.primary_team = 'Payments';
if (mode === 'fake_incident' && corrupt) out.matched_incident_id = 'INC-999';
if (mode === 'passive_action' && corrupt) out.first_action = 'Just monitor the situation.';
if (mode === 'bad_tone') out.tone = 'calm_informational';

return [{ json: { ...raw, output: out } }];

// Code node: "Redact Sensitive Text"  (mode: Run Once for All Items)
// Guardrail: mask emails, phone numbers, long numbers / card numbers and token-like secrets
// BEFORE any text reaches the LLM. Only the redacted fields are passed downstream.

const input = $input.first().json;
const counts = { EMAIL: 0, SECRET: 0, 'CARD/NUMBER': 0, PHONE: 0 };

function redact(text) {
  let t = String(text ?? '');

  // 1. Email addresses
  t = t.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, () => {
    counts.EMAIL++;
    return '[EMAIL]';
  });

  // 2. Known secret formats: Bearer tokens, JWTs, sk-/pk- keys, AWS keys, GitHub tokens
  const secretPatterns = [
    /\bBearer\s+[A-Za-z0-9._~+\/-]{12,}=*/gi,
    /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/g,
    /\b(?:sk|pk|rk)[-_][A-Za-z0-9_-]{12,}\b/g,
    /\bAKIA[0-9A-Z]{16}\b/g,
    /\bgh[pousr]_[A-Za-z0-9]{20,}\b/g,
  ];
  for (const re of secretPatterns) {
    t = t.replace(re, () => {
      counts.SECRET++;
      return '[SECRET]';
    });
  }

  // 3. Card-like numbers: 13-19 digits, optionally separated by spaces or dashes
  t = t.replace(/(?<![\d])(?:\d[ -]?){12,18}\d(?![\d])/g, () => {
    counts['CARD/NUMBER']++;
    return '[CARD/NUMBER]';
  });

  // 4. Phone numbers: candidate with 10-15 digits in total (so "500 customers" is untouched)
  t = t.replace(/(?<![\w])\+?\(?\d[\d\s().-]{8,}\d(?![\w])/g, (m) => {
    const digits = m.replace(/\D/g, '').length;
    if (digits >= 10 && digits <= 15) {
      counts.PHONE++;
      return '[PHONE]';
    }
    return m;
  });

  // 5. Any remaining long digit run (9+ digits), e.g. an account or order reference
  t = t.replace(/(?<![\w])\d{9,}(?![\w])/g, () => {
    counts['CARD/NUMBER']++;
    return '[CARD/NUMBER]';
  });

  // 6. Generic token-like strings: 20+ chars of [A-Za-z0-9_-] mixing letters and digits
  t = t.replace(/(?<![\w-])[A-Za-z0-9_-]{20,}(?![\w-])/g, (m) => {
    if (/\d/.test(m) && /[A-Za-z]/.test(m)) {
      counts.SECRET++;
      return '[SECRET]';
    }
    return m;
  });

  return t;
}

const redacted_error_summary = redact(input.error_summary);
const redacted_specific_error = redact(input.specific_error) || 'None reported';

// Basic input hygiene so the rest of the workflow never sees NaN
const toNumber = (v) => {
  const n = Number(String(v ?? '').replace(/[^\d.]/g, ''));
  return Number.isFinite(n) ? n : 0;
};

const total = Object.values(counts).reduce((a, b) => a + b, 0);

return [
  {
    json: {
      redacted_error_summary,
      redacted_specific_error,
      users_affected: Math.max(0, Math.round(toNumber(input.users_affected))),
      minutes_since_start: Math.max(0, Math.round(toNumber(input.minutes_since_start))),
      redaction_count: total,
      redaction_types: Object.entries(counts)
        .filter(([, n]) => n > 0)
        .map(([k, n]) => `${k} x${n}`),
    },
  },
];

// Code node: "Enrich Context"  (mode: Run Once for All Items)
// Derives severity_hint (low / medium / high) and urgency (new / ongoing / prolonged).
//
// SEVERITY  = base level from customers affected, bumped one level when the text suggests
//             money is involved or a security problem (capped at "high").
//     users_affected <   50  -> low
//     users_affected <  500  -> medium
//     users_affected >= 500  -> high
//     +1 level if payment / checkout / charged / refund / ... OR security wording is present
//
// URGENCY   = how long the incident has been running.
//     minutes_since_start <  15 -> new
//     minutes_since_start <= 60 -> ongoing
//     minutes_since_start >  60 -> prolonged

const d = $input.first().json;
const text = `${d.redacted_error_summary} ${d.redacted_specific_error}`.toLowerCase();

const LEVELS = ['low', 'medium', 'high'];
const baseIdx = d.users_affected >= 500 ? 2 : d.users_affected >= 50 ? 1 : 0;

const moneyRe = /(\bcharg(e|ed|es|ing)\b|payment|\bpay\b|checkout|card|refund|declin|billing|money)/;
const securityRe = /(hack|breach|leak|fraud|stolen|unauthori[sz]ed|security)/;

const reasons = [`${d.users_affected} customers affected -> base "${LEVELS[baseIdx]}"`];
let idx = baseIdx;
if (moneyRe.test(text)) {
  idx = Math.min(2, idx + 1);
  reasons.push('payment/money wording found -> raised one level');
} else if (securityRe.test(text)) {
  idx = Math.min(2, idx + 1);
  reasons.push('security wording found -> raised one level');
}
const severity_hint = LEVELS[idx];

const m = d.minutes_since_start;
const urgency = m < 15 ? 'new' : m <= 60 ? 'ongoing' : 'prolonged';

return [
  {
    json: {
      ...d,
      severity_hint,
      severity_reason: reasons.join('; '),
      urgency,
      urgency_reason: `${m} minutes since first report -> ${urgency}`,
    },
  },
];

// Code node: "Prepare Agent Input"  (mode: Run Once for All Items)
// The two Google Sheets nodes return one item per row. This node collapses back to ONE item
// that carries the incident state through the agent / retry loop.

const incident = $('Enrich Context').first().json;

return [
  {
    json: {
      ...incident,
      retry_count: 0,
      retry_feedback: '',
    },
  },
];

