parameters.jsCode:
// Code node: "Output Checks"  (mode: Run Once for All Items)
// Guardrail applied after every agent attempt. Checks against the REAL sheet data
// (loaded by the "Load Team Directory" / "Load Incident History" nodes), not the agent's memory.
//
//  1. primary_team is an exact team name from the Team Directory
//     (and contact / channel returned by the agent match that directory row)
//  2. severity is not downplayed: high severity needs an escalating action, never "just monitor"
//  3. matched_incident_id is "None" or a real ID from the Incident History
//     (and the resolving team quoted matches the sheet; the history tool must actually have been called)
//
// $runIndex = 0 for the first attempt, 1 for retry #1, 2 for retry #2.

const base = $('Prepare Agent Input').first().json;
const raw = $input.first().json;
const attempt = $runIndex;

const teams = $('Load Team Directory').all().map((i) => i.json);
const history = $('Load Incident History').all().map((i) => i.json);

const failures = [];
const out = raw.output && typeof raw.output === 'object' ? raw.output : null;

if (!out) {
  failures.push(
    `The agent did not return a valid structured answer${raw.error ? ` (${String(raw.error).slice(0, 200)})` : ''}.`
  );
}

const norm = (s) => String(s ?? '').trim();
const teamRow = out ? teams.find((t) => norm(t.team) === norm(out.primary_team)) : null;

if (out) {
  // ---- Check 1: exact team name ----
  if (!teamRow) {
    failures.push(
      `primary_team "${norm(out.primary_team)}" is not an exact team name in the Team Directory. ` +
        `Valid names: ${teams.map((t) => `"${t.team}"`).join(', ')}.`
    );
  } else {
    if (norm(out.on_call_contact) !== norm(teamRow.on_call_contact)) {
      failures.push(
        `on_call_contact "${norm(out.on_call_contact)}" does not match the Team Directory value "${teamRow.on_call_contact}" for ${teamRow.team}.`
      );
    }
    if (norm(out.escalation_channel) !== norm(teamRow.escalation_channel)) {
      failures.push(
        `escalation_channel "${norm(out.escalation_channel)}" does not match the Team Directory value "${teamRow.escalation_channel}" for ${teamRow.team}.`
      );
    }
  }

  // ---- Check 2: severity not downplayed ----
  if (base.severity_hint === 'high') {
    const action = norm(out.first_action);
    const downplay =
      /\b(just|simply|only)\s+(monitor|watch|wait)|wait and see|keep an eye|no action|do nothing|hold off|\bmonitor(ing)?\b\s*(it|this|the situation)?\s*\.?$/i;
    // "page" only counts when it is the verb ("page the on-call engineer"), not the noun ("product page")
    const escalates = /\b(page\s+(the\s+)?(on-?call|engineer|team)|escalat|contact|call|notify|alert|post|message|raise|ping|open an? (incident|ticket))\w*/i;
    if (downplay.test(action) || !escalates.test(action)) {
      failures.push(
        `severity_hint is HIGH but first_action ("${action}") is passive. Give an escalating first action ` +
          `(for example contact the on-call person or post in the escalation channel now). Do not recommend only monitoring.`
      );
    }
  }

  // ---- Check 3: matched incident ID is None or real ----
  const id = norm(out.matched_incident_id);
  if (id.toLowerCase() !== 'none') {
    const row = history.find((h) => norm(h.incident_id) === id);
    if (!row) {
      failures.push(
        `matched_incident_id "${id}" does not exist in the Incident History. Use "None" if nothing matches. ` +
          `Real IDs: ${history.map((h) => h.incident_id).join(', ')}.`
      );
    } else if (norm(out.matched_incident_resolving_team) !== norm(row.resolving_team)) {
      failures.push(
        `matched_incident_resolving_team "${norm(out.matched_incident_resolving_team)}" does not match the history for ${id} (it was resolved by "${row.resolving_team}").`
      );
    }
  }
}

// Evidence of which tools the agent really called
const steps = Array.isArray(raw.intermediateSteps) ? raw.intermediateSteps : [];
const toolsCalled = steps.map((s) => String(s?.action?.tool ?? '')).filter(Boolean);
const calledHistory = toolsCalled.some((t) => /incident_history/i.test(t));
const calledDirectory = toolsCalled.some((t) => /team_directory/i.test(t));

if (out && norm(out.matched_incident_id).toLowerCase() !== 'none' && !calledHistory) {
  failures.push('You cited a past incident but never called the incident_history tool. Call it before citing an incident.');
}
if (out && !calledDirectory) {
  failures.push('You did not call the team_directory tool. Team and contact details must come from that tool.');
}

const matchedRow =
  out && norm(out.matched_incident_id).toLowerCase() !== 'none'
    ? history.find((h) => norm(h.incident_id) === norm(out.matched_incident_id)) ?? null
    : null;

return [
  {
    json: {
      ...base,
      agent_output: out,
      tools_called: toolsCalled,
      history_tool_called: calledHistory,
      directory_tool_called: calledDirectory,
      // Authoritative values taken from the sheet, never from the model
      directory_row: teamRow ?? null,
      matched_incident_row: matchedRow,
      checks_passed: failures.length === 0,
      failures,
      attempt,
      max_retries: 2,
    },
  },
];

// Code node: "Build Retry Input"  (mode: Run Once for All Items)
// Runs only when a check failed AND retries remain. Sends the failure reasons back to the agent.

const c = $input.first().json;
const retry_count = c.attempt + 1;

const previous = c.agent_output
  ? JSON.stringify({
      primary_team: c.agent_output.primary_team,
      matched_incident_id: c.agent_output.matched_incident_id,
      first_action: c.agent_output.first_action,
    })
  : '(no valid answer)';

const retry_feedback =
  `RETRY ${retry_count} of ${c.max_retries}. Your previous answer was rejected by the automatic checks.\n` +
  `Previous answer: ${previous}\n` +
  `Reasons:\n${c.failures.map((f, i) => `${i + 1}. ${f}`).join('\n')}\n` +
  `Fix every reason above, use your tools again if needed, and answer in the required format.`;

// Carry only the original incident state forward (not the previous agent output)
const {
  agent_output, tools_called, history_tool_called, directory_tool_called, directory_row,
  matched_incident_row, checks_passed, failures, attempt, max_retries,
  ...incident
} = c;

return [{ json: { ...incident, retry_count, retry_feedback } }];

// Code node: "Manual Routing Message"  (mode: Run Once for All Items)
// Reached when the checks still fail after the maximum of 2 retries.

const c = $input.first().json;
const one = (v) => String(v ?? '').replace(/\s*\n+\s*/g, ' ').trim();
const failures = c.failures ?? [];

const json = {
  'Result': 'MANUAL ROUTING NEEDED',
  'What to do': 'Ask a team lead or the duty manager to route this incident. The assistant could not give a verified recommendation after 3 attempts (1 try + 2 retries).',
  'What was reported': one(c.redacted_error_summary),
  'Exact error': one(c.redacted_specific_error),
  'Seriousness': `${String(c.severity_hint).toUpperCase()}, ${c.urgency} (${c.users_affected} customers, ${c.minutes_since_start} min)`,
  'Why it stopped': failures.slice(0, 3).map(one).join(' | '),
};

// TEST-ONLY snippet, appended just before the final `return` of "Manual Routing Message" in the test harness workflow.
// It adds machine-readable fields so the test scripts can verify results. The submitted workflow does not contain it.
Object.assign(json, {
  status: 'manual_routing_required',
  severity_hint: c.severity_hint,
  urgency: c.urgency,
  tools_called: c.tools_called,
  redacted_error_summary: c.redacted_error_summary,
  failures,
  attempts: (c.attempt ?? 0) + 1,
  summary: Object.entries(json).map(([k, v]) => `${k}: ${v}`).join('\n'),
});

return [{ json }];

// Code node: "Rule-Based Validation"  (mode: Run Once for All Items)
// Decision validation, part 1 (deterministic). Part 2 is the LLM judge.
//  - Does the first action fit the severity?
//  - Does the communication tone fit the urgency?

const c = $input.first().json;
const o = c.agent_output;
const action = String(o.first_action ?? '');
const tone = String(o.tone ?? '').trim();
const notes = [];

// ---- Action vs severity ----
// "page" only counts as an escalation when it is the verb ("page the on-call engineer"), not the noun ("product page")
const escalates = /\b(page\s+(the\s+)?(on-?call|engineer|team)|escalat|contact|call|notify|alert|post|message|raise|ping|open an? (incident|ticket))\w*/i;
const overReaction = /\bpage\s+(the\s+)?(on-?call|engineer|team)|\b(emergency|immediately|urgent(ly)?|right now|all hands)\b/i;
const passive = /\b(just|simply|only)\s+(monitor|watch|wait)|wait and see|keep an eye|no action|do nothing/i;

let action_fits_severity = true;
if (c.severity_hint === 'high' && (passive.test(action) || !escalates.test(action))) {
  action_fits_severity = false;
  notes.push('High severity but the first action is not an escalation.');
} else if (c.severity_hint === 'medium' && passive.test(action)) {
  action_fits_severity = false;
  notes.push('Medium severity but the first action is only passive monitoring.');
} else if (c.severity_hint === 'low' && overReaction.test(action)) {
  action_fits_severity = false;
  notes.push('Low severity but the first action sounds like an emergency escalation.');
}

// ---- Tone vs urgency ----
const allowed = {
  new: ['calm_informational', 'reassuring_proactive'],
  ongoing: ['reassuring_proactive', 'apologetic_urgent'],
  prolonged: ['apologetic_urgent'],
};
const tone_fits_urgency = (allowed[c.urgency] ?? []).includes(tone);
if (!tone_fits_urgency) {
  notes.push(`Urgency is "${c.urgency}" but tone is "${tone}" (expected one of: ${(allowed[c.urgency] ?? []).join(', ')}).`);
}

return [{ json: { ...c, rule_validation: { action_fits_severity, tone_fits_urgency, notes } } }];

